import {resaleQuote} from './summer-rules.js';
import {balances,money} from './accounting.js';
import {settlementSteps} from './settlement.js';
export function renderSettlement(s,{top,foot,attrs,recovery}){
 const b=balances(s),steps=settlementSteps(s),step=s.liquidation.step,current=steps[step],rec=recovery(s);
 const descriptions={receivable:b.receivable?`待收货款 ${money(b.receivable)} 元，实际回收 ${money(rec.cash)} 元，确认损失 ${money(rec.loss)} 元。`:'没有待收货款，这一步可以直接确认。',inventory:b.inventory?`剩余原料和包材账面成本 ${money(b.inventory)} 元，清售可收回 ${money(resaleQuote(s,'inventory'))} 元。`:'原材料和包材已经清空，这一步无需出售。',equipment:b.equipment?`摊桌和压汁器账面价值 ${money(b.equipment)} 元，出售可收回 ${money(resaleQuote(s,'equipment'))} 元。`:'没有需要出售的设备，这一步可以直接确认。',payable:`应付账款尚有 ${money(b.payable)} 元；当前最多偿还 ${money(Math.min(b.cash,b.payable))} 元。`,loan:`借款本金尚有 ${money(b.loan)} 元；当前最多归还 ${money(Math.min(b.cash,b.loan))} 元。`,wages:`已经确认的应付职工薪酬 ${money(b.wagesPayable)} 元；当前最多支付 ${money(Math.min(b.cash,b.wagesPayable))} 元。`,interest:`已经计提的应付利息 ${money(b.interestPayable)} 元；当前最多支付 ${money(Math.min(b.cash,b.interestPayable))} 元。`};
 return `<div class="card-content">${top('按顺序把这一步处理好',`${step+1} / ${steps.length}`)}<h2 class="card-title" id="card-title" data-settlement-kind="${current.kind}" tabindex="-1">${current.title}</h2><div class="current-settlement"><p class="card-lead">${descriptions[current.kind]}</p><p>钱盒现有 <strong>${money(b.cash)} 元</strong>。</p></div>${current.debt?'<p class="detail-note">偿还已经记过的本金或欠款，不重复减少利润。钱不够时，未偿债务继续保留。</p>':'<p class="detail-note">低于账面价值回收的差额，计入处置损失。没有对应资产时，不产生交易。</p>'}<details><summary>看看完整的清算顺序</summary><div class="liquidation-list">${steps.map((v,i)=>`<div class="liquidation-step ${i===step?'active':i<step?'done':''}"><b>${i<step?'✓':i+1}</b><div><strong>${v.title}</strong><small>${i<step?'已处理':i===step?'正在处理':'之后处理'}</small></div></div>`).join('')}</div></details><button class="mini-link" ${attrs('quick')}>一起处理剩余各项 ↗</button></div>${foot(current.action,'settle',current.debt?'未偿债务会继续留在账上。':'这一步处理完，再进入下一项。',step)}`;
}
